int main(int argc,char** argv){if(argc!=2)return 2;PoliticalGovernanceAgencyState state;PoliticalSuccessionPlayerReceipt receipt{"leader","result:9",2,3};PoliticalGovernanceAgencyOffer offer{"political_governance_agency_offer:1","p","org","office","leader","delegate","grant.appoint","grant.finance",4,0,5,8,20,receipt};state.offers.insert(offer.id,offer);PoliticalGovernanceAgencyAnswer answer{"political_governance_agency_answer:2",offer.id,"delegate",6,true,receipt};state.answers.insert(answer.id,answer);PoliticalGovernanceAgencyRevocation revoke{"political_governance_agency_revocation:5",offer.id,"leader",4,9,receipt};state.revocations.insert(revoke.id,revoke);PoliticalGovernanceAgencyIssue issue{"political_governance_agency_issue:3",offer.id,answer.id,"delegate","executor","politics_governance_agency_authority:4",7,receipt};state.issues.insert(issue.id,issue);CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);if(!visit_political_governance_agency_checkpoint(writer,state).ok||!writer.finish().ok)return 3;std::ofstream out(argv[1],std::ios::binary);out.write(reinterpret_cast<const char*>(bytes.data()),bytes.size());return out.good()?0:4;}
